package com.aaliyun.leadnews.wemedia.audit;
import com.aaliyun.leadnews.common.context.UserContext;import com.aaliyun.leadnews.feign.article.ArticleInternalClient;import com.aaliyun.leadnews.feign.schedule.ScheduleInternalClient;import com.aaliyun.leadnews.model.foundation.*;import com.aaliyun.leadnews.wemedia.domain.*;import com.aaliyun.leadnews.wemedia.mapper.*;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.slf4j.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class AuditPublicationService {private static final Logger log=LoggerFactory.getLogger(AuditPublicationService.class);private final WmNewsMapper news;private final WmUserMapper users;private final ArticleInternalClient article;private final ScheduleInternalClient schedule;private final ObjectMapper json;public AuditPublicationService(WmNewsMapper n,WmUserMapper u,ArticleInternalClient a,ScheduleInternalClient s,ObjectMapper j){news=n;users=u;article=a;schedule=s;json=j;}
 public void publish(Long newsId){try{UserContext.setInternal(true);UserContext.setUserType("SYSTEM");WmNews n=news.selectById(newsId);if(n==null||n.getStatus()!=WmNewsStatus.APPROVED)return;WmUser u=users.selectById(n.getUserId());var command=new CreateArticleCommand(n.getId(),n.getUserId(),u==null?"unknown":u.getNickname(),n.getChannelId(),n.getTitle(),n.getLayout(),read(n.getCoverImages(),new TypeReference<List<String>>(){}),n.getLabels(),read(n.getContent(),new TypeReference<List<ArticleContentItemDTO>>(){}),n.getPublishTime());ArticleCreatedResponse created=article.create(command);if(n.getPublishTime()!=null&&n.getPublishTime().isAfter(LocalDateTime.now())){schedule.create(new ScheduleTaskCommand(created.articleId(),n.getPublishTime()));news.update(null,new LambdaUpdateWrapper<WmNews>().eq(WmNews::getId,newsId).eq(WmNews::getStatus,WmNewsStatus.APPROVED).set(WmNews::getStatus,WmNewsStatus.WAITING).set(WmNews::getArticleId,created.articleId()));}else article.publish(created.articleId());}catch(RuntimeException e){log.warn("audit_publish_finalize success=false newsId={} errorCode={}",newsId,e.getClass().getSimpleName());}finally{UserContext.clear();}}
 @Scheduled(fixedDelayString="${audit.publish-recovery-interval-ms:10000}") public void recoverApproved(){news.selectList(new LambdaQueryWrapper<WmNews>().eq(WmNews::getStatus,WmNewsStatus.APPROVED).eq(WmNews::getAuditSource,"AI_AUTO_APPROVED").last("LIMIT 50")).forEach(n->publish(n.getId()));}
 private<T>T read(String s,TypeReference<T>t){try{return json.readValue(s,t);}catch(Exception e){throw new IllegalStateException("Stored JSON invalid");}}
}
